use vstd::prelude::*;
use vstd::vec::Vec;

verus! {

    /// Given an input vector `arr` of i32 and a threshold `k`,
    /// returns a new vector `res` of the same length such that
    /// for each index i:
    ///   if arr[i] > k then res[i] == -1
    ///   else                res[i] == arr[i]
    pub fn replace(arr: &Vec<i32>, k: i32) -> Vec<i32>
        ensures result.len() == arr.len()
        ensures forall(|i: usize| i < arr.len() ==>
            if arr[i] > k {
                result[i] == -1
            } else {
                result[i] == arr[i]
            })
    {
        // We build up the result vector element by element.
        let mut res: Vec<i32> = Vec::with_capacity(arr.len());
        let mut i: usize = 0;

        // Loop over all indices 0 .. arr.len()
        while i < arr.len() {
            // Invariants to help the verifier
            invariant i <= arr.len();
            invariant res.len() == i;
            invariant forall(|j: usize| j < i ==>
                if arr[j] > k {
                    res[j] == -1
                } else {
                    res[j] == arr[j]
                });
            decreases arr.len() - i;

            let x = arr[i];
            if x > k {
                res.push(-1);
            } else {
                res.push(x);
            }
            i += 1;
        }

        res
    }

}